import { useState, useEffect, useRef, useCallback } from 'react';
import { useTheme } from '@emotion/react';
import { Button, useToast } from '@docs-front/ui';
import { useNavigate } from '@tanstack/react-router';
import { useQuery, useMutation } from '@tanstack/react-query';
import { HTTPError } from 'ky';

import { postProductsDraftExport } from '@/api/products/mutation';
import { getProductFileDownload } from '@/api/products/query';
import { useModal } from '@/hooks/useModal';
import { getProductFileStatusPollingOptions } from '@/query/options/products';
import type { ImageItem } from '@/routes/_authenticated/start/-components/steps/Step4ImageSelect';
import { FreeTrialExhaustedModal } from '@/routes/_authenticated/credit-plan/-components/InsufficientCreditModal/FreeTrialExhaustedModal';
import {
  GenerateInProgressScreen
} from '@/routes/_authenticated/-components/GenerateInProgressScreen/GenerateInProgressScreen';
import { GENERATE_PROGRESS_STEP_COUNT } from '@/routes/_authenticated/-components/GenerateInProgressScreen/GenerateInProgressScreen.constants';
import type { Language } from '@/schema/api/products/products';
import type { Theme } from '@docshunt/docs-editor-wasm';
import {
  StyledGenCenter,
  StyledModalOverlay,
  StyledModalBox,
  StyledModalIconCircle,
  StyledModalFooter,
  StyledFileInfoBox,
  StyledBtnOutlined,
  StyledBtnFilled,
} from '@/routes/_authenticated/start/-route.style';
import { Check, Download, FileText } from 'lucide-react';

interface Step6Props {
  selectedTemplateFileId: string | null;
  selectedDocument: {
    type: 'export' | 'draftProduct' | 'draftExport';
    id: string;
    productContents: string;
  } | null;
  prompt: string;
  images: ImageItem[];
  referenceFiles: File[];
  language: Language;
  documentTheme?: Theme;
  exportedProductId: string | null;
  onExportedProductIdChange: (id: string | null) => void;
  onGoHome: () => void;
  onCompleted?: () => void;
  startToken?: number;
}

export function Step6Generate({
  selectedTemplateFileId,
  selectedDocument,
  prompt,
  images,
  referenceFiles,
  language,
  documentTheme,
  exportedProductId,
  onExportedProductIdChange,
  onGoHome,
  onCompleted,
  startToken = 0,
}: Step6Props) {
  const theme = useTheme();
  const toast = useToast();
  const modal = useModal();
  const navigate = useNavigate();
  const [currentStep, setCurrentStep] = useState(0);
  const [completed, setCompleted] = useState(false);
  const [failed, setFailed] = useState(false);
  const [showDownloadModal, setShowDownloadModal] = useState(false);
  const downloadFileName = '사업계획서_초안.hwpx';
  const lastStartedTokenRef = useRef(0);
  const hasHandledRef = useRef(false);

  // API: 생성 요청
  const exportMutation = useMutation({
    mutationFn: () => {
      if (!selectedTemplateFileId) throw new Error('템플릿을 선택해주세요.');
      return postProductsDraftExport({
        contents: {
          userPrompt: prompt,
          productContents:
            selectedDocument?.type === 'draftProduct'
              ? selectedDocument.productContents
              : '',
          exportProductFileId:
            selectedDocument?.type === 'export' ||
            selectedDocument?.type === 'draftExport'
              ? selectedDocument.id
              : undefined,
          productImagesMetaData: [],
          svgSuggestions: images
            .filter((img) => img.checked)
            .map((img) => ({
              name: img.title,
              info: img.prompt,
              position: img.position,
              gen_by: img.genBy,
            })),
          templateFileId: selectedTemplateFileId,
          language,
          theme: documentTheme,
        },
        referenceFiles: referenceFiles.length > 0 ? referenceFiles : undefined,
      });
    },
    onSuccess: (result) => onExportedProductIdChange(result.data.exportedProductId),
    onError: (error) => {
      if (
        error instanceof HTTPError &&
        error.response?.status === 400 &&
        error.message ===
          '무료 이용 한도를 초과했습니다. 구독 후 무제한으로 이용하세요.'
      ) {
        modal.openModal(({ isOpen, onClose }) => (
          <FreeTrialExhaustedModal
            isOpen={isOpen}
            onClose={() => {
              onClose();
              navigate({ to: '/start/settings' });
            }}
          />
        ));
        return;
      }

      setFailed(true);
      toast.open({ content: '생성 요청에 실패했습니다.', duration: 3000 });
    },
  });

  useEffect(() => {
    if (startToken === 0 || exportedProductId) return;
    if (lastStartedTokenRef.current === startToken) return;

    lastStartedTokenRef.current = startToken;
    exportMutation.mutate();
  }, [exportMutation, exportedProductId, startToken]);

  // 상태 폴링
  const { data: statusData } = useQuery({
    ...getProductFileStatusPollingOptions(exportedProductId ?? ''),
    enabled: !!exportedProductId && !completed && !failed,
  });

  useEffect(() => {
    const fileStatus = statusData?.data.status;
    if (!fileStatus || hasHandledRef.current) return;

    switch (fileStatus) {
      case 'PENDING': setCurrentStep(1); break;
      case 'PROGRESS': setCurrentStep(3); break;
      case 'COMPLETED': {
        hasHandledRef.current = true;
        setCurrentStep(GENERATE_PROGRESS_STEP_COUNT);
        // 완료 즉시 에디터로 이동
        if (exportedProductId) {
          onCompleted?.();
          navigate({ to: '/d/$productFileId', params: { productFileId: String(exportedProductId) }, search: { fromGenerate: true } });
        } else {
          setCompleted(true);
        }
        break;
      }
      case 'FAILED':
        hasHandledRef.current = true;
        setFailed(true);
        toast.open({ content: '생성에 실패했습니다.', duration: 3000 });
        break;
    }
  }, [exportedProductId, navigate, onCompleted, statusData, toast]);

  const handleGoHome = onGoHome;

  const handleDownload = useCallback(async () => {
    if (!exportedProductId) return;
    try {
      const blob = await getProductFileDownload(exportedProductId);
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = downloadFileName;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      setShowDownloadModal(true);
    } catch {
      toast.open({ content: '다운로드에 실패했습니다.', duration: 3000 });
    }
  }, [exportedProductId, downloadFileName, toast]);

  const handleQuickEdit = () => {
    if (exportedProductId) {
      navigate({ to: '/d/$productFileId', params: { productFileId: String(exportedProductId) }, search: { fromGenerate: true } });
    } else {
      toast.open({ content: '생성된 문서가 없습니다.', duration: 2000 });
    }
  };

  if (failed) {
    return (
      <StyledGenCenter>
        <div style={{
          width: 64, height: 64, borderRadius: '50%', background: '#F04452',
          display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: 24,
        }}>
          <span style={{ color: '#FFFFFF', fontSize: 28, fontWeight: 700 }}>!</span>
        </div>
        <h2 style={{ fontSize: 20, fontWeight: 600, marginBottom: 12, letterSpacing: '-0.02em', color: '#25262C' }}>
          사업계획서 생성에 실패했습니다
        </h2>
        <p style={{ fontSize: 14, color: '#B5B9C4', textAlign: 'center', lineHeight: 1.6, marginBottom: 32, letterSpacing: '-0.02em' }}>
          잠시 후 다시 시도해주세요.
        </p>
        <button
          type="button"
          onClick={handleGoHome}
          style={{ background: 'none', border: 'none', color: theme.color.textGray, fontSize: 14, cursor: 'pointer', padding: '8px 16px', letterSpacing: '-0.02em' }}
        >
          처음으로
        </button>
      </StyledGenCenter>
    );
  }

  if (completed) {
    return (
      <>
        <StyledGenCenter>
          <div style={{
            width: 64, height: 64, borderRadius: '50%', background: theme.color.main,
            display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: 24,
          }}>
            <Check size={28} color={theme.color.white} strokeWidth={3} />
          </div>
          <h2 style={{ fontSize: 20, fontWeight: 600, marginBottom: 12, letterSpacing: '-0.02em', color: '#25262C' }}>
            사업계획서 생성이 완료되었습니다
          </h2>
          <p style={{ fontSize: 14, color: '#B5B9C4', textAlign: 'center', lineHeight: 1.6, marginBottom: 32, letterSpacing: '-0.02em' }}>
            작성된 사업계획서를 확인하고 다운로드할 수 있습니다.
          </p>
          <div style={{ display: 'flex', gap: 12 }}>
            <Button variant="outlined" size="large" onClick={handleQuickEdit}>바로수정(beta)</Button>
            <Button variant="filled" size="large" onClick={handleDownload}>
              <Download size={16} style={{ marginRight: 6 }} />
              사업계획서 다운로드
            </Button>
          </div>
          <button
            type="button"
            onClick={handleGoHome}
            style={{ marginTop: 16, background: 'none', border: 'none', color: theme.color.textGray, fontSize: 14, cursor: 'pointer', padding: '8px 16px', letterSpacing: '-0.02em' }}
          >
            처음으로
          </button>

        </StyledGenCenter>

        {/* ─── 모달 6: 다운로드 완료 ──────────────────────────── */}
        {showDownloadModal && (
          <StyledModalOverlay onClick={() => setShowDownloadModal(false)}>
            <StyledModalBox $width={420} onClick={(e) => e.stopPropagation()} style={{ textAlign: 'center' }}>
              <StyledModalIconCircle $variant="success">
                <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#22C55E" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/>
                  <polyline points="22 4 12 14.01 9 11.01"/>
                </svg>
              </StyledModalIconCircle>

              <div style={{ fontSize: 18, fontWeight: 600, marginBottom: 8, letterSpacing: '-0.02em', color: '#25262C' }}>
                사업계획서 다운로드 완료
              </div>
              <div style={{ fontSize: 14, color: '#6E7687', letterSpacing: '-0.02em', lineHeight: 1.6 }}>
                파일이 성공적으로 다운로드되었습니다.
              </div>

              <StyledFileInfoBox>
                <FileText size={16} color="#2C81FC" />
                <span style={{ fontSize: 14, fontWeight: 500, color: '#25262C', letterSpacing: '-0.02em' }}>{downloadFileName}</span>
              </StyledFileInfoBox>

              <StyledModalFooter style={{ justifyContent: 'center', marginTop: 16 }}>
                <StyledBtnOutlined onClick={() => { setShowDownloadModal(false); handleQuickEdit(); }}>
                  바로수정(beta)
                </StyledBtnOutlined>
                <StyledBtnFilled onClick={() => setShowDownloadModal(false)}>확인</StyledBtnFilled>
              </StyledModalFooter>
            </StyledModalBox>
          </StyledModalOverlay>
        )}
      </>
    );
  }

  return <GenerateInProgressScreen currentStep={currentStep} />;
}
