import { createFileRoute, Navigate } from '@tanstack/react-router';

import { Step6Generate } from '@/routes/_authenticated/start/-components/steps/Step6Generate';
import { useStartFlow } from '@/routes/_authenticated/start/-startFlow.context';

export const Route = createFileRoute('/_authenticated/start/generate/')({
  component: RouteComponent
});

function RouteComponent() {
  const {
    selectedDraftTemplate,
    hasGeneratedSuggestions,
    selectedTemplateFileId,
    selectedDocument,
    prompt,
    images,
    referenceFiles,
    language,
    theme,
    exportedProductId,
    setExportedProductId,
    generateStartToken,
    resetFlow,
    clearCompletedFlow
  } = useStartFlow();

  if (!selectedDraftTemplate) {
    return <Navigate to="/start/template" replace />;
  }

  if (!hasGeneratedSuggestions) {
    return <Navigate to="/start/upload" replace />;
  }

  if (!exportedProductId && generateStartToken === 0) {
    return <Navigate to="/start/settings" replace />;
  }

  return (
    <Step6Generate
      selectedTemplateFileId={selectedTemplateFileId}
      selectedDocument={selectedDocument}
      prompt={prompt}
      images={images}
      referenceFiles={referenceFiles}
      language={language}
      documentTheme={theme}
      exportedProductId={exportedProductId}
      onExportedProductIdChange={setExportedProductId}
      onGoHome={() => {
        void resetFlow();
      }}
      onCompleted={() => {
        void clearCompletedFlow();
      }}
      startToken={generateStartToken}
    />
  );
}
